import{_ as r,p as t,q as l,s as e,R as a,t as i,Y as s,n as p}from"./framework-e1bed10d.js";const d={},o=s(`<h1 id="vibe-coding-团队协作技巧" tabindex="-1"><a class="header-anchor" href="#vibe-coding-团队协作技巧" aria-hidden="true">#</a> Vibe Coding 团队协作技巧</h1><blockquote><p>和其他人一起用 Vibe Coding 做项目</p></blockquote><p>你好，我是鱼皮。</p><p>在实际工作中，很多项目是团队协作完成的。</p><p>你可能会想：用 AI 开发还需要团队协作吗？每个人自己用 AI 不就行了？</p><p>其实不然。团队协作中有很多问题需要解决，比如不同人用 AI 生成的代码不一致（A 用 React，B 用 Vue）、A 改了代码 B 不知道、大家都在改同一个文件导致冲突等等……</p><p>在 Vibe Coding 团队协作中，除了传统的团队协作方法，还可以利用 AI 开发工具的特性来提升效率。本文我就来分享一些团队使用 Vibe Coding 的最佳实践。</p><h2 id="一、代码规范和风格" tabindex="-1"><a class="header-anchor" href="#一、代码规范和风格" aria-hidden="true">#</a> 一、代码规范和风格</h2><p>团队协作的第一步是统一代码规范。</p><h3 id="为什么需要统一规范" tabindex="-1"><a class="header-anchor" href="#为什么需要统一规范" aria-hidden="true">#</a> 为什么需要统一规范？</h3><p>如果每个人用 AI 生成的代码风格都不一样，项目会变得很混乱。比如 A 用 React Class 组件，B 用函数组件；A 用 CSS Modules，B 用 Tailwind；A 的变量名是 camelCase，B 的是 snake_case……</p><p>这样的代码很难维护，也很难协作。所以，团队需要统一的代码规范。</p><h3 id="建立代码规范文档" tabindex="-1"><a class="header-anchor" href="#建立代码规范文档" aria-hidden="true">#</a> 建立代码规范文档</h3><p>可以创建一个 <code>CODE_STYLE.md</code> 文档，明确规定下面的内容。</p><p>1）技术栈规范：</p><ul><li>前端框架：React 19 + TypeScript</li><li>状态管理：Zustand</li><li>样式方案：Tailwind CSS</li><li>路由方案：React Router v6</li></ul><p>2）代码风格规范：</p><ul><li>组件：函数式组件 + Hooks</li><li>命名：组件用 PascalCase，函数用 camelCase，常量用 UPPER_SNAKE_CASE</li><li>文件组织：一个组件一个文件，文件名和组件名一致</li><li>导入顺序：React → 第三方库 → 项目内部模块</li></ul><p>3）注释规范：</p><ul><li>复杂逻辑必须加注释</li><li>注释要说明 &quot;为什么&quot; 而不只是 &quot;是什么&quot;</li><li>使用 JSDoc 格式为函数添加文档</li></ul><p>建议把这个文档放在项目根目录，让所有人都能看到。</p><h3 id="使用-linter-和-formatter" tabindex="-1"><a class="header-anchor" href="#使用-linter-和-formatter" aria-hidden="true">#</a> 使用 Linter 和 Formatter</h3><p>光有文档还不够，很多人明明有文档就是不看，需要用工具来强制执行。</p><p><img src="https://pic.yupi.icu/1/image-20260105172241747.png" alt=""></p><p>ESLint 是代码检查工具，能自动发现代码中的问题和不规范的地方。</p><p>Prettier 是代码格式化工具，能自动统一代码格式，比如缩进、换行、引号等。</p><p>双剑合璧，专治烂代码！</p><p>如果你不理解这些工具，没关系，可以直接让 AI 帮你安装和配置：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请帮我配置 ESLint 和 Prettier，确保团队代码风格一致。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>AI 会帮你在项目根目录创建 <code>.eslintrc.json</code> 代码检查配置文件：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;extends&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token string">&quot;eslint:recommended&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;plugin:react/recommended&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;plugin:@typescript-eslint/recommended&quot;</span>
  <span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;rules&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;react/react-in-jsx-scope&quot;</span><span class="token operator">:</span> <span class="token string">&quot;off&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;@typescript-eslint/no-explicit-any&quot;</span><span class="token operator">:</span> <span class="token string">&quot;error&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;no-console&quot;</span><span class="token operator">:</span> <span class="token string">&quot;warn&quot;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>创建 <code>.prettierrc</code> 代码格式化配置文件：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;semi&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
  <span class="token property">&quot;singleQuote&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
  <span class="token property">&quot;tabWidth&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span>
  <span class="token property">&quot;trailingComma&quot;</span><span class="token operator">:</span> <span class="token string">&quot;es5&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;printWidth&quot;</span><span class="token operator">:</span> <span class="token number">100</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>并且在 <code>package.json</code> 中添加脚本：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;scripts&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;lint&quot;</span><span class="token operator">:</span> <span class="token string">&quot;eslint . --ext .ts,.tsx&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;lint:fix&quot;</span><span class="token operator">:</span> <span class="token string">&quot;eslint . --ext .ts,.tsx --fix&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;format&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prettier --write \\&quot;src/**/*.{ts,tsx}\\&quot;&quot;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样，大家提交代码前运行 <code>npm run lint:fix &amp;&amp; npm run format</code>，代码就会自动符合规范。</p><h3 id="统一-ai-配置" tabindex="-1"><a class="header-anchor" href="#统一-ai-配置" aria-hidden="true">#</a> 统一 AI 配置</h3><p>如果团队都用 Cursor，可以在项目中添加 <code>.cursorrules</code> 文件，统一 AI 的行为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>项目：【项目名称】

技术栈：
- React 18 + TypeScript
- Tailwind CSS
- Zustand

代码规范：
- 使用函数式组件
- 所有组件必须有 TypeScript 类型定义
- 样式只用 Tailwind CSS
- 不使用 any 类型

请所有团队成员都遵循这些规范。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样，不同人用 AI 生成的代码风格会更一致。</p><p>如果团队使用 Claude 或其他 AI 工具，也可以通过类似的方式统一规范。比如在每次对话开始时，先让 AI 读取项目的规范文档，或者在系统提示词中加入团队的代码规范。不同工具的具体做法可能不同，建议查看 AI 工具的官方文档。</p><h2 id="二、ai-编程工具的团队协作功能" tabindex="-1"><a class="header-anchor" href="#二、ai-编程工具的团队协作功能" aria-hidden="true">#</a> 二、AI 编程工具的团队协作功能</h2><p>现代 AI 编程工具提供了专门的团队协作功能，能大大提升团队效率。</p><h3 id="cursor-团队版" tabindex="-1"><a class="header-anchor" href="#cursor-团队版" aria-hidden="true">#</a> Cursor 团队版</h3>`,44),c={href:"https://cursor.com/cn/docs/account/teams",target:"_blank",rel:"noopener noreferrer"},u=e("p",null,"1）团队管理和权限控制",-1),h=e("p",null,"可以创建团队，邀请成员，设置不同的角色和权限。管理员可以控制谁能访问哪些功能，查看团队的使用情况和账单。",-1),m=e("p",null,"2）共享配置文件",-1),v=e("p",null,"通过共享规则文件，团队可以统一 AI 的行为规范。所有成员使用的 AI 都会遵循相同的代码规范、技术栈要求和输出格式，确保生成的代码风格一致。",-1),b=e("p",null,"3）使用分析和监控",-1),g=e("p",null,"团队管理员可以查看团队的 AI 使用情况，包括哪些成员使用最多、使用了哪些模型、花费了多少成本等。这能帮助优化团队的 AI 使用策略。",-1),k=e("p",null,[e("img",{src:"https://pic.yupi.icu/1/cursor-dashboard.jpeg",alt:""})],-1),f=e("h3",{id:"claude-共享能力",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#claude-共享能力","aria-hidden":"true"},"#"),a(" Claude 共享能力")],-1),A={href:"https://www.anthropic.com/news/projects",target:"_blank",rel:"noopener noreferrer"},_=s(`<p>1）项目级别的知识库</p><p>可以为每个项目创建独立的知识库，上传项目相关的文档、代码、规范等。团队成员在这个项目中使用 Claude 时，AI 会自动参考这些知识，保持上下文一致。</p><p><img src="https://pic.yupi.icu/1/claudeprojectknowledge.png" alt=""></p><p>2）自定义指令</p><p>可以为每个项目设置自定义指令，比如 “使用正式的语气”、“从数据分析师的角度回答” 等。团队成员使用时，AI 会自动遵循这些指令。</p><p>3）对话分享</p><p>Claude Team 用户可以将优秀的对话分享到团队的活动流中。其他成员可以看到别人是如何使用 AI 的，学习不同的提问技巧和解决方案，提升整个团队的 AI 使用水平。</p><p><img src="https://pic.yupi.icu/1/claudeshare.jpeg" alt=""></p><p>4）团队共享 <code>CLAUDE.md</code> 文件</p><p>即使不使用 Projects 功能，也可以把 <code>CLAUDE.md</code> 文件用 Git 来管理，实现团队成员的共同分享和维护。</p><p>每当发现 Claude 做错了什么，就将它添加到 <code>CLAUDE.md</code> 中，这样 Claude 下次就知道不要这样做了。这个文件会逐渐沉淀团队的开发经验和规范，成为团队的共享知识库。</p><h2 id="三、文档驱动开发" tabindex="-1"><a class="header-anchor" href="#三、文档驱动开发" aria-hidden="true">#</a> 三、文档驱动开发</h2><p>好的文档是团队协作的基础。</p><h3 id="项目文档的重要性" tabindex="-1"><a class="header-anchor" href="#项目文档的重要性" aria-hidden="true">#</a> 项目文档的重要性</h3><p>在团队中，文档比个人开发时更重要。因为你写的代码不只是给自己看的，还要给其他人看。好的文档能让团队成员快速了解项目，减少沟通成本。</p><p>必备的文档包括：</p><ul><li>README.md：项目概述和使用说明</li><li>CONTRIBUTING.md：如何参与开发</li><li>CODE_STYLE.md：代码规范</li><li>API.md：API 接口文档</li><li>CHANGELOG.md：版本更新记录</li></ul><h3 id="readme-md-的内容" tabindex="-1"><a class="header-anchor" href="#readme-md-的内容" aria-hidden="true">#</a> README.md 的内容</h3><p>README.md 是项目的门面，就像一本书的封面和目录。它是新成员加入项目时第一个看的文件，也是其他开发者了解你项目的窗口。一个好的 README 能让人快速理解项目、快速上手开发。</p><p>一个好的 README.md 应该包含：</p><ul><li>项目简介：这个项目是做什么的，解决什么问题</li><li>快速开始：如何安装依赖、配置环境、运行项目</li><li>技术栈：用了哪些技术、为什么选择这些技术</li><li>目录结构：主要文件夹的作用</li><li>开发规范：代码风格、提交规范等</li><li>常见问题：新人容易遇到的问题和解决方案</li></ul><h3 id="api-文档" tabindex="-1"><a class="header-anchor" href="#api-文档" aria-hidden="true">#</a> API 文档</h3><p>如果项目有后端 API，要写清楚每个接口的用法。可以用 Swagger、Postman 等工具或者 AI 来生成 API 文档，也可以手写 Markdown 文档。</p><p>每个接口要说明：</p><ul><li>请求方法和路径</li><li>请求参数（类型、是否必填、说明）</li><li>响应格式</li><li>错误码说明</li><li>使用示例</li></ul><h3 id="让-ai-帮你写文档" tabindex="-1"><a class="header-anchor" href="#让-ai-帮你写文档" aria-hidden="true">#</a> 让 AI 帮你写文档</h3><p>写文档很枯燥，但 AI 可以帮你。</p><p>如果你使用 Cursor、Claude Code 等 AI 编程工具，工具会自动读取项目结构作为上下文，你甚至不用自己贴代码，直接说：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请为这个项目生成 API 文档
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>AI 就能根据代码自动生成。</p><p>如果使用其他 AI 工具，可以手动贴代码：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请为这个 API 接口生成文档：
【贴上你的代码】

文档应该包括：接口说明、请求参数、响应格式、使用示例
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>AI 会生成一份基础的文档，你再根据实际情况调整。</p><h2 id="四、git-协作流程" tabindex="-1"><a class="header-anchor" href="#四、git-协作流程" aria-hidden="true">#</a> 四、Git 协作流程</h2><p>Git 是一个版本控制系统，也是团队协作的核心工具。就像给代码拍照存档，可以随时回到之前的任何版本。它能记录谁在什么时候改了什么代码，团队成员可以同时开发不同功能，最后再合并到一起。</p>`,35),x={href:"https://www.codefather.cn/course/1789189862986850306/section/1789190804671012866",target:"_blank",rel:"noopener noreferrer"},I=s('<h3 id="分支管理策略" tabindex="-1"><a class="header-anchor" href="#分支管理策略" aria-hidden="true">#</a> 分支管理策略</h3><p>分支就像是代码的平行世界。你可以在自己的分支里随便改代码，不会影响别人。改好了再合并到主分支，就像把你的工作成果搬到正式版本里。</p><p>团队开发要利用好分支功能，常见的分支策略是：</p><ul><li>main 分支：稳定的生产代码，只接受经过测试的代码</li><li>develop 分支：开发分支，日常开发在这里进行</li><li>feature 分支：每个新功能开一个分支，比如 <code>feature/user-login</code>、<code>feature/post-editor</code></li><li>bugfix 分支：修复 bug 时开的分支，比如 <code>bugfix/login-error</code></li></ul><p>工作流程是：</p><ol><li>从 develop 分支创建 feature 分支</li><li>在 feature 分支上开发，开发完成后提交 Pull Request</li><li>经过审查后合并到 develop</li><li>定期将 develop 合并到 main</li></ol><p><img src="https://pic.yupi.icu/1/gitcooperate大.jpeg" alt=""></p><h3 id="提交规范" tabindex="-1"><a class="header-anchor" href="#提交规范" aria-hidden="true">#</a> 提交规范</h3>',8),q={href:"https://www.conventionalcommits.org/zh-hans/v1.0.0/",target:"_blank",rel:"noopener noreferrer"},C=s(`<p>比如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>feat: 添加用户登录功能
fix: 修复导航栏在移动端的显示问题
docs: 更新 API 文档
style: 格式化代码
refactor: 重构用户服务
test: 添加登录功能的测试
chore: 更新依赖包
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>类型 + 冒号 + 空格 + 简短描述，大家一看就知道这次提交做了什么。</p><p>现在很多 AI 编程工具都支持生成提交信息，更容易遵循规范。</p><p><img src="https://pic.yupi.icu/1/image-20260105172920015.png" alt=""></p><h3 id="pull-request-流程" tabindex="-1"><a class="header-anchor" href="#pull-request-流程" aria-hidden="true">#</a> Pull Request 流程</h3><p>Pull Request（简称 PR）是一种代码合并请求。当你在自己的分支上完成开发后，不要直接合并到主分支，而是创建一个 PR，让其他人审查你的代码。审查通过后，才能合并。这就像提交作业让老师批改，批改通过了才算完成。</p><p>具体流程是这样的：</p><ul><li>创建 PR：在 GitHub 上创建 PR，写清楚这次改动做了什么，为什么要这样改。</li><li>代码审查：至少一个其他成员审查代码，检查功能、代码质量、是否符合规范。</li><li>讨论和修改：如果有问题，在 PR 中讨论，提交者根据反馈修改。</li><li>合并代码：审查通过后，合并到目标分支。</li></ul><p>这个流程虽然多了一步，但能大大提高代码质量。</p><p><img src="https://pic.yupi.icu/1/image-20260105173137083.png" alt=""></p><h3 id="解决冲突" tabindex="-1"><a class="header-anchor" href="#解决冲突" aria-hidden="true">#</a> 解决冲突</h3><p>多人协作时，代码冲突是常见问题。当两个人修改了同一个文件的同一部分，Git 会提示冲突。</p><p>解决冲突的步骤是：首先拉取最新代码 <code>git pull origin develop</code>，Git 会标记出冲突的地方。然后手动编辑文件，决定保留哪部分代码。解决完冲突后，要测试确保功能正常，最后提交解决后的代码。</p><p>为了减少冲突，建议：</p><ol><li>经常拉取最新代码，不要长时间不同步</li><li>功能开发完就及时合并，不要拖太久</li><li>如果要修改公共文件，提前和团队沟通</li></ol><h2 id="五、代码审查流程" tabindex="-1"><a class="header-anchor" href="#五、代码审查流程" aria-hidden="true">#</a> 五、代码审查流程</h2><p>代码审查（Code Review）是保证团队代码质量的关键。</p><h3 id="为什么要做代码审查" tabindex="-1"><a class="header-anchor" href="#为什么要做代码审查" aria-hidden="true">#</a> 为什么要做代码审查？</h3><p>代码审查有很多好处。</p><p>首先，能在代码上线前就发现潜在的 Bug，避免问题流入生产环境。其次，能统一代码风格，让项目代码保持一致，不会出现每个人写的代码风格都不一样的情况。</p><p>更重要的是，代码审查是一个很好的学习机会。审查者能看到别人的代码思路，被审查者能得到改进建议，双方都能学到东西。而且，知道代码会被审查，写的时候自然就会更认真，这能从源头提高代码质量。</p><h3 id="审查的重点" tabindex="-1"><a class="header-anchor" href="#审查的重点" aria-hidden="true">#</a> 审查的重点</h3><p>审查代码时，重点关注这些方面：</p><ol><li>功能正确性：代码是否正确实现了需求？有没有遗漏的边界情况？</li><li>代码质量：代码是否清晰易懂？有没有重复代码？命名是否规范？</li><li>性能问题：有没有明显的性能问题？数据结构选择是否合理？</li><li>安全问题：有没有安全漏洞？用户输入是否验证？</li><li>测试覆盖：是否有足够的测试？测试是否覆盖了主要场景？</li></ol><h3 id="审查的技巧" tabindex="-1"><a class="header-anchor" href="#审查的技巧" aria-hidden="true">#</a> 审查的技巧</h3><p>审查时要注意方法。不要只说 “这里不对”，要说清楚为什么不对、应该怎么改。要用建议的语气，而不是命令的语气。比如 “我建议这里用 useMemo 优化性能” 而不是 “这里必须用 useMemo”。当然，团队如果有硬性要求除外。</p><p>如果有多个问题，分清主次。先指出重要的问题（比如 bug、安全漏洞），再提改进建议（比如命名、注释）。</p><p>审查不是一次性的，可以多轮讨论。第一轮指出主要问题，修改后再审查，确认没问题再合并。</p><h3 id="让-ai-辅助审查" tabindex="-1"><a class="header-anchor" href="#让-ai-辅助审查" aria-hidden="true">#</a> 让 AI 辅助审查</h3><p>可以让 AI 帮你做初步审查：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请审查这段代码，从功能、性能、安全、代码质量等角度分析：
【贴上代码】
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>AI 会给你一份详细的审查报告。但要注意，AI 的审查不能完全替代人工审查，最终还是要人来把关。</p><h4 id="使用-cursor-的-bugbot" tabindex="-1"><a class="header-anchor" href="#使用-cursor-的-bugbot" aria-hidden="true">#</a> 使用 Cursor 的 BugBot</h4>`,34),w={href:"https://cursor.com/cn/bugbot",target:"_blank",rel:"noopener noreferrer"},y=s('<p>你可以在 Cursor 中直接使用这个功能，让 AI 帮你做初步的代码审查。</p><p><img src="https://pic.yupi.icu/1/image-20260105173323498.png" alt=""></p><h4 id="claude-code-自动化代码审查" tabindex="-1"><a class="header-anchor" href="#claude-code-自动化代码审查" aria-hidden="true">#</a> Claude Code 自动化代码审查</h4><p>如果使用 Claude Code，可以在代码审查的 Pull Request 中标记 <code>@.claude</code>，这样 Claude 会自动把审查建议添加到 <code>CLAUDE.md</code> 文件中。再利用 GitHub Action 实现自动化更新，这样文档会逐渐沉淀团队的代码质量标准和常见问题。</p><p>这也是 Claude Code 创始人推荐的做法，让代码审查的经验自动积累下来。</p><h4 id="多个-ai-交叉验证" tabindex="-1"><a class="header-anchor" href="#多个-ai-交叉验证" aria-hidden="true">#</a> 多个 AI 交叉验证</h4><p>为了更保险，可以让多个不同的 AI 审查同一段代码。比如先让 Claude 审查一遍，再让 GPT 审查一遍，对比它们的建议。</p><p>不同的 AI 可能会发现不同的问题，交叉验证能提高审查的全面性。</p><h2 id="六、团队协作最佳实践" tabindex="-1"><a class="header-anchor" href="#六、团队协作最佳实践" aria-hidden="true">#</a> 六、团队协作最佳实践</h2><p>基于我的经验，这里总结一些团队协作的最佳实践。</p><p>💡 这部分主要是给团队负责人或管理者看的。如果你不是团队管理者，只是团队成员，这部分可以直接跳过，或者了解一下就好。</p><h3 id="定期同步" tabindex="-1"><a class="header-anchor" href="#定期同步" aria-hidden="true">#</a> 定期同步</h3><p>团队要定期开会同步进度，比如每天的站会（5 ~ 10 分钟），每周的周会（30 ~ 60 分钟）。</p><p>站会主要说三件事：昨天做了什么、今天计划做什么、遇到了什么问题。</p><p>周会可以深入讨论技术方案、分享经验、规划下周工作。</p><p>除了会议，还可以用工具同步。比如用 Jira 等工具管理任务，用企微、飞书、Slack 等工具日常沟通，用 Notion、语雀等工具共享文档。</p><h3 id="结对编程" tabindex="-1"><a class="header-anchor" href="#结对编程" aria-hidden="true">#</a> 结对编程</h3><p>对于复杂的功能，可以尝试结对编程。两个人一起开发，一个人写代码（Driver），一个人审查和提建议（Navigator），这样不仅能提高代码质量，也能促进知识分享。</p><p>说实话，我很少见到有公司真的这么做，因为成本太高了。</p><p>不过仔细想想，在 Vibe Coding 中，和 AI 一起开发，不就是一种结对编程吗？</p><p>AI 是你的编程搭档，你提需求，它写代码；你审查，它改进。这种 “人机结对” 可能比 “人人结对” 更高效。</p><h3 id="知识分享" tabindex="-1"><a class="header-anchor" href="#知识分享" aria-hidden="true">#</a> 知识分享</h3><p>团队要建立知识分享机制。可以每周安排一个人分享最近学到的技术、遇到的问题、总结的经验；或者分享如何用 AI 解决某个难题、如何优化某个功能的性能、如何避免某个常见的坑；或者把各种技术和业务知识沉淀为文档。这样能让整个团队的水平都提升，也能避免重复踩坑。</p><p>我们团队就是用语雀知识库来共享文档的，每个人遇到的问题、总结的经验、学到的技巧都记录在上面，新人加入时直接看知识库就能快速上手。</p><p><img src="https://pic.yupi.icu/1/使用知识库数量.png" alt=""></p><h3 id="建立共享资源" tabindex="-1"><a class="header-anchor" href="#建立共享资源" aria-hidden="true">#</a> 建立共享资源</h3><p>团队可以建立一些共享资源，比如：</p><ul><li>提示词模板库：常用的提示词模板</li><li>代码片段库：常用的组件和函数</li><li>问题解决方案库：遇到的问题和解决方法</li><li>最佳实践文档：总结的经验和技巧</li></ul><p>这些资源能让新人快速上手，也能提高整个团队的效率。</p><p>可以通过 Git + GitHub 来管理和共享代码文件，也可以用各种云盘软件来存储多媒体，选择团队习惯的工具就好。</p><h3 id="明确分工" tabindex="-1"><a class="header-anchor" href="#明确分工" aria-hidden="true">#</a> 明确分工</h3><p>虽然都用 AI，但还是要明确分工。谁负责前端、谁负责后端、谁负责测试、谁负责部署。每个人有自己的职责，避免重复工作或遗漏。</p><p>同时，要避免 AI 依赖症。不要所有人都依赖 AI，要有人能在 AI 出问题时顶上。保持团队的技术能力，不要完全依赖工具。</p><p>这也是为什么如今程序员依然关键 —— AI 只是工具，真正理解业务、把控质量、做出决策的还是人。<strong>所以不用担心 AI 会淘汰程序员，会用 AI 的程序员只会变得更强大。</strong></p><p>💡 虽然在企业中大家会分工合作，但我建议大家努力拓宽自己的能力边界。前端会一点后端、后端会一点前端、测试会一点开发，这样不仅能更好地理解整个系统，也能在关键时刻顶上。在 AI 时代，争取成为能独立完成全栈项目的 <strong>超级个体</strong>，会让你更有竞争力。</p><h2 id="写在最后" tabindex="-1"><a class="header-anchor" href="#写在最后" aria-hidden="true">#</a> 写在最后</h2><p>团队协作开发比个人开发复杂得多，但也更有价值。一个配合默契的团队 + AI，能做出远超个人 + AI 的项目。</p><p>最后总结一下本文重点，团队协作开发中需要：</p><ol><li>统一代码规范：用文档和工具确保代码风格一致。</li><li>利用 AI 工具的团队功能：比如 Cursor 团队版、Claude Projects 等，实现配置共享、知识共享、对话分享，让 AI 成为团队的共享大脑</li><li>文档驱动开发：写好文档，让团队成员快速了解项目</li><li>规范 Git 流程：用分支管理、提交规范、PR 流程保证代码质量</li><li>认真做代码审查：审查不是形式，而是提高质量的关键。</li><li>建立协作机制：定期同步、结对编程、知识分享、共享资源</li><li>明确分工：每个人有自己的职责，同时保持技术能力。</li></ol><p>Vibe Coding 不会改变团队协作的本质，它只是一个工具。好的团队协作，需要的是清晰的规范、良好的沟通和互相的信任。</p><p>非常感谢您的阅读 🙏🏻！</p><h2 id="推荐资源" tabindex="-1"><a class="header-anchor" href="#推荐资源" aria-hidden="true">#</a> 推荐资源</h2>',42),P={href:"https://ai.codefather.cn",target:"_blank",rel:"noopener noreferrer"},E={href:"https://www.codefather.cn",target:"_blank",rel:"noopener noreferrer"},R={href:"https://www.mianshiya.com",target:"_blank",rel:"noopener noreferrer"},j={href:"https://www.laoyujianli.com",target:"_blank",rel:"noopener noreferrer"},S={href:"https://ai.mianshiya.com",target:"_blank",rel:"noopener noreferrer"};function G(B,T){const n=p("ExternalLinkIcon");return t(),l("div",null,[o,e("p",null,[a("Cursor 提供了专门的 "),e("a",c,[a("团队版"),i(n)]),a("，包含下面这些功能：")]),u,h,m,v,b,g,k,f,e("p",null,[a("Claude 提供了 "),e("a",A,[a("Projects 功能"),i(n)]),a("，特别适合团队协作：")]),_,e("p",null,[a("💡 如果你想系统学习并掌握 Git，可以阅读 "),e("a",x,[a("鱼皮的 Git & GitHub 学习路线"),i(n)]),a("。")]),I,e("p",null,[a("统一的提交信息能让团队更容易追踪变更。建议使用 "),e("a",q,[a("Conventional Commits 规范"),i(n)]),a("，这是一种标准化的提交信息格式，让每次提交的目的一目了然。")]),C,e("p",null,[a("Cursor 提供了一个专门的代码审查工具叫 "),e("a",w,[a("BugBot"),i(n)]),a("，它能自动扫描你的代码，找出潜在的 Bug、性能问题和安全漏洞，并且快速修复。")]),y,e("p",null,[a("1）鱼皮 AI 导航网站："),e("a",P,[a("AI 资源大全、最新 AI 资讯、免费 AI 教程"),i(n)])]),e("p",null,[a("2）编程导航学习圈："),e("a",E,[a("学习路线、编程教程、实战项目、求职宝典、交流答疑"),i(n)])]),e("p",null,[a("3）程序员面试八股文："),e("a",R,[a("实习/校招/社招高频考点、企业真题解析"),i(n)])]),e("p",null,[a("4）程序员写简历神器："),e("a",j,[a("专业模板、丰富例句、直通面试"),i(n)])]),e("p",null,[a("5）1 对 1 模拟面试："),e("a",S,[a("实习/校招/社招面试拿 Offer 必备"),i(n)])])])}const V=r(d,[["render",G],["__file","11VibeCodingtuanduixiezuojiqiao.html.vue"]]);export{V as default};
